{
  "name": "FTDI USB转串口适配器",
  "name_en": "FTDI USB-to-Serial Adapter",
  "manufacturer": "FTDI",
  "description": "基于 FTDI/FT232 芯片的 USB 转串口接口设备，用于在计算机与采用 UART/TTL 串行通信的实验仪器、微控制器或自制电子模块之间传输数据。部分型号还可通过 CBUS 引脚实现简单的数字输出与输入读取，常用于实验室中的串口通信、设备调试和基础 I/O 控制。",
  "description_en": "A USB-to-serial interface device based on FTDI/FT232 chips, used to transfer data between a computer and laboratory instruments, microcontrollers, or custom electronics that communicate over UART/TTL serial links. Some models also expose CBUS pins for simple digital output and input reading, making them useful for serial communications, instrument debugging, and basic I/O control in the lab.",
  "tag_hints": [
    "USB-to-UART",
    "serial communication",
    "FT232",
    "UART/TTL interface",
    "CBUS GPIO",
    "instrument debugging",
    "USB serial adapter"
  ],
