      "action_name": "auto-baudrate",
      "description": "定义波特率",
      "description_en": "define baud rate"
    },
    {
      "action_name": "auto-bytesize",
      "description": "定义数据位长度",
      "description_en": "define byte size"
    },
    {
      "action_name": "auto-cbus_read",
      "description": "读取CBUS引脚状态",
      "description_en": "read CBUS pin states"
    },
    {
      "action_name": "auto-cbus_setup",
      "description": "配置CBUS引脚掩码和初始状态",
      "description_en": "configure CBUS pin mask and initial state"
    },
    {
      "action_name": "auto-cbus_write",
      "description": "设置CBUS输出状态",
      "description_en": "set CBUS output state"
    },
    {
      "action_name": "auto-close",
      "description": "关闭设备连接",
      "description_en": "close the device connection"
    },
    {
      "action_name": "auto-dsrdtr",
      "description": "定义DSR/DTR流控",
      "description_en": "define DSR/DTR flow control"
    },
