      "description_en": "get DSR/DTR flow control setting"
    },
    {
      "action_name": "auto-getParity",
      "description": "获取校验位设置",
      "description_en": "get parity setting"
    },
    {
      "action_name": "auto-getRtsCts",
      "description": "获取RTS/CTS流控设置",
